from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

VERSION = "4.3"
BLOCK_ID = 14778
CFG_STORES = 10
CHUNK = 9900
MAX_BODY = 2 * 1024 * 1024
N_BITS = 8          # 1-Bit-Eingänge/-Ausgänge für Szene 1–8
MAX_SCENES = 32
SEASON_HOURS = (7, 14, 22)  # Messzeitpunkte Tagesmittel (T7 + T14 + T22 + T22) / 4
SEASON_LIMIT = 16.0         # Sommer ab Tagesmittel >= 16 °C (Heizgrenze)
TYPES = ("switch", "dim", "value", "blind", "mode", "rgbw", "heat", "lock")   # lock: Sperre 1 Bit, 1 = gesperrt, 0 = freigegeben
# Heizung (Raum): key = Sollwert-KO (DPT 9.001), status = Ist-Temperatur
HEATK = ("modeKey", "setStatus", "modeStatus", "valveKey")   # Betriebsart (8 Bit, im HS DPT 5.010; Werte wie DPT 20.102), Soll-RM, Betriebsart-RM, Ventil
HVAC = (0, 1, 2, 3, 4)       # Auto, Komfort, Standby, Nacht, Frostschutz
RGBW = ("rKey", "gKey", "bKey", "wKey")
# Gewerke: Licht, Rollo (Beschattung), Tore, Dachfenster, Heizung, Sonstiges
TRADES = ("licht", "rollo", "tor", "dachfenster", "heizung", "sonst")

PAGE_Z = ''


# ====================================================================== Hilfen
def pack(obj):
    raw = base64.b64encode(zlib.compress(json.dumps(obj, separators=(",", ":")).encode("utf-8"), 9))
    return [raw[i:i + CHUNK] for i in range(0, len(raw), CHUNK)] or [b""]


def unpack(chunks):
    raw = b"".join(c if isinstance(c, bytes) else str(c or "").encode("ascii") for c in chunks if c)
    if not raw:
        return None
    return json.loads(zlib.decompress(base64.b64decode(raw)).decode("utf-8"))


def norm_key(k):
    """Wie auf der Webseite: 1/2/3 → CO@1_2_3, ohne Präfix → CO@…, Präfix groß."""
    k = str(k or "").strip()
    if not k:
        return ""
    if len(k) > 3 and k[2] == "@" and k[:2].isalpha():
        k = k[:2].upper() + k[2:]
    else:
        k = "CO@" + k
    body = k[3:]
    if k.startswith("CO@") and "/" in body and all(p.isdigit() for p in body.split("/")):
        k = "CO@" + body.replace("/", "_")
    return k


def to_num(v):
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v if v is not None else "").strip().lower()
    if s in ("true", "on", "ein"):
        return 1.0
    if s in ("false", "off", "aus"):
        return 0.0
    try:
        return float(s.replace(",", "."))
    except ValueError:
        return None


def fmt_val(v):
    n = to_num(v)
    if n is None:
        return str(v)
    if n == int(n):
        return str(int(n))
    return ("%.4f" % n).rstrip("0").rstrip(".")


# ---------------------------------------------------------------- Feiertage / Zeitprogramm Heizung
STATES = ("BW", "BY", "BE", "BB", "HB", "HH", "HE", "MV", "NI", "NW", "RP", "SL", "SN", "ST", "SH", "TH")
PRE_TEMPS = (10, 5, 0, -5, -10, -15, -20)          # Stützpunkte Vorlaufzeit (°C)
PRE_DEFAULT = [30, 45, 60, 90, 120, 150, 180]      # Minuten (Di–Sa)
PRE_MONDAY = [45, 60, 90, 120, 150, 180, 240]      # Minuten (Montag bzw. nach freien Tagen)
PRE_DAYS = 6                                       # Zeilen Mo, Di, Mi, Do, Fr, Sa


def easter(y):
    """Ostersonntag (Gauß/Meeus, gregorianisch)."""
    a, b, c = y % 19, y // 100, y % 100
    d, e = b // 4, b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = c // 4, c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    return datetime.date(y, (h + l - 7 * m + 114) // 31, ((h + l - 7 * m + 114) % 31) + 1)


def holidays(y, state="BY", mh=True):
    """Gesetzliche Feiertage {datum: Name} je Bundesland."""
    D = datetime.date
    e = easter(y)
    td = datetime.timedelta
    h = {D(y, 1, 1): "Neujahr", e - td(2): "Karfreitag", e + td(1): "Ostermontag", D(y, 5, 1): "Tag der Arbeit",
         e + td(39): "Christi Himmelfahrt", e + td(50): "Pfingstmontag", D(y, 10, 3): "Tag der Deutschen Einheit",
         D(y, 12, 25): "1. Weihnachtstag", D(y, 12, 26): "2. Weihnachtstag"}
    if state in ("BW", "BY", "ST"):
        h[D(y, 1, 6)] = "Heilige Drei Koenige"
    if state == "BE" or (state == "MV" and y >= 2023):
        h[D(y, 3, 8)] = "Frauentag"
    if state == "BB":
        h[e] = "Ostersonntag"
        h[e + td(49)] = "Pfingstsonntag"
    if state in ("BW", "BY", "HE", "NW", "RP", "SL"):
        h[e + td(60)] = "Fronleichnam"
    if state == "SL" or (state == "BY" and mh):
        h[D(y, 8, 15)] = "Mariae Himmelfahrt"
    if state == "TH" and y >= 2019:
        h[D(y, 9, 20)] = "Weltkindertag"
    if state in ("BB", "MV", "SN", "ST", "TH") or (state in ("HB", "HH", "NI", "SH") and y >= 2018):
        h[D(y, 10, 31)] = "Reformationstag"
    if state in ("BW", "BY", "NW", "RP", "SL"):
        h[D(y, 11, 1)] = "Allerheiligen"
    if state == "SN":
        d = D(y, 11, 22)
        while d.weekday() != 2:
            d -= td(1)
        h[d] = "Buss- und Bettag"
    return h


def norm_hhmm(t, default):
    try:
        hh, mm = str(t).split(":")
        hh, mm = int(hh), int(mm)
        if 0 <= hh < 24 and 0 <= mm < 60:
            return "%02d:%02d" % (hh, mm)
    except (ValueError, TypeError):
        pass
    return default


def norm_plan(p):
    """Zeitprogramm einer Heizung: Kommen/Gehen an Arbeitstagen, Vorlauf nach Außentemperatur."""
    p = p if isinstance(p, dict) else {}
    pre = p.get("pre") if isinstance(p.get("pre"), list) else []
    if len(pre) == len(PRE_TEMPS) and not isinstance(pre[0], list):      # alte Form: eine Zeile für alle Tage
        pre = [list(pre) for _ in range(PRE_DAYS)]
    rows = []
    for i in range(PRE_DAYS):
        r = pre[i] if i < len(pre) and isinstance(pre[i], list) and len(pre[i]) == len(PRE_TEMPS) else (PRE_MONDAY if i == 0 else PRE_DEFAULT)
        rows.append([int(max(0, min(720, to_num(x) or 0))) for x in r])
    out = {"on": bool(p.get("on")), "wd": 6 if to_num(p.get("wd")) == 6 else 5,
           "k": norm_hhmm(p.get("k"), "07:00"), "g": norm_hhmm(p.get("g"), "17:00"),
           "ko": norm_hvac(p.get("ko", 1)), "ksp": bool(p.get("ksp")), "kv": to_num(p.get("kv")) or 21,
           "go": norm_hvac(p.get("go", 3)), "gsp": bool(p.get("gsp")), "gv": to_num(p.get("gv")) or 18,
           "pre": rows,                                  # je Wochentag Mo..Sa: Minuten für 10 … −20 °C
           "af": bool(p.get("af", True))}                # erster Arbeitstag nach freien Tagen: Montags-Vorlauf
    return out


def pre_minutes(pre, t):
    """Vorlaufzeit (min) für Außentemperatur t, linear zwischen den Stützpunkten, außerhalb begrenzt.
    Unbekannte Temperatur -> längster Vorlauf (sicher warm)."""
    if t is None:
        return max(pre)
    if t >= PRE_TEMPS[0]:
        return pre[0]
    if t <= PRE_TEMPS[-1]:
        return pre[-1]
    for i in range(len(PRE_TEMPS) - 1):
        t0, t1 = PRE_TEMPS[i], PRE_TEMPS[i + 1]
        if t1 <= t <= t0:
            return pre[i] + (pre[i + 1] - pre[i]) * (t0 - t) / float(t0 - t1)
    return pre[-1]


def norm_cal(c):
    c = c if isinstance(c, dict) else {}
    days = {}
    for k, v in (c.get("days") or {}).items() if isinstance(c.get("days"), dict) else []:
        try:
            datetime.date(*[int(x) for x in str(k).split("-")])
            days[str(k)] = 1 if v in (1, "1", True) else 0
        except (ValueError, TypeError):
            pass
    return {"state": c.get("state") if c.get("state") in STATES else "BY", "mh": bool(c.get("mh", True)), "days": days,
            "bridge": bool(c.get("bridge"))}           # Brückentage automatisch frei


def norm_hvac(o):
    """Betriebsart 0–4 (Auto, Komfort, Standby, Nacht, Frost) oder None (= nicht senden)."""
    n = to_num(o)
    if n is None or int(n) not in HVAC:
        return None
    return int(n)


def func_keys(f):
    """Alle KOs, deren Werte die Seite/der Baustein für die Anzeige braucht."""
    ks = [f["status"] or f["key"]]
    if f["type"] == "heat":
        ks += [f["key"]] + [f.get(k) for k in HEATK]
    ks += [f.get(k) for k in RGBW]
    return [k for k in ks if k]


def norm_color(c):
    """[R, G, B, W] in 0–100 %; Standard warmweiß (nur W)."""
    if not isinstance(c, (list, tuple)) or len(c) != 4:
        return [0, 0, 0, 100]
    out = []
    for x in c:
        n = to_num(x)
        out.append(max(0.0, min(100.0, n)) if n is not None else 0)
    return out


def new_id(prefix):
    return prefix + "%06x" % random.randrange(1 << 24)


def norm_config(cfg):
    """Einrichtung vervollständigen und bereinigen (auch für Daten von der Webseite)."""
    if not isinstance(cfg, dict):
        cfg = {}
    lim = to_num(cfg.get("tempLimit"))
    if lim == 15.0 and not cfg.get("seasonV"):   # alter Standard (Außentemperatur 15 °C) -> Tagesmittel 16 °C
        lim = SEASON_LIMIT
    delay = to_num(cfg.get("rainDelay"))
    burst = to_num(cfg.get("sendBurst"))
    pause = to_num(cfg.get("sendPause"))
    out = {"title": str(cfg.get("title") or "Szenen")[:60],
           # Sensoren für alle Gruppen: KNX-KO über das Gateway, leer = Baustein-Eingang
           "duskKey": norm_key(cfg.get("duskKey")),
           "rainKey": norm_key(cfg.get("rainKey")),
           "tempKey": norm_key(cfg.get("tempKey")),
           "tempLimit": lim if lim is not None else SEASON_LIMIT,   # Sommer ab Tagesmittel … °C
           "seasonV": 2,
           "rainDelay": int(max(0, min(240, delay if delay is not None else 5))),
           # v4.3: Buslast – höchstens sendBurst Telegramme am Stück, dann sendPause Sekunden Pause (0 = ohne Begrenzung)
           "sendBurst": int(max(0, min(50, burst if burst is not None else 5))),
           "sendPause": round(max(0.0, min(10.0, pause if pause is not None else 1.0)), 1),
           "cal": norm_cal(cfg.get("cal")),          # Feiertagskalender für Zeitprogramme der Heizung
           "groups": []}
    seen_g = set()
    for g in cfg.get("groups") or []:
        if not isinstance(g, dict):
            continue
        gid = str(g.get("id") or "")
        if not gid or gid in seen_g:
            gid = new_id("g")
        seen_g.add(gid)
        scenes = [s for s in (g.get("scenes") or []) if isinstance(s, dict)][:MAX_SCENES]
        if not scenes:
            scenes = [{"name": "Szene %d" % (i + 1)} for i in range(8)]
        scenes = [{"name": str(s.get("name") or "Szene %d" % (i + 1))[:40]} for i, s in enumerate(scenes)]
        n = len(scenes)
        try:
            trig = int(g.get("trigger", 0))
        except (TypeError, ValueError):
            trig = 0
        ng = {
            "id": gid,
            "name": str(g.get("name") or "Gruppe")[:40],
            "trigger": 1 if trig > 0 else 0,   # 1 = über die Baustein-Ein-/Ausgänge (nur eine Gruppe)
            "triggerKey": norm_key(g.get("triggerKey")),
            # 0 = KNX DPT 17.001: Wert 0–63 = Szene 1–64 (Standard)
            # 1 = Wert 1 = Szene 1 (wie Matrix-Baustein), 0 = keine Szene aktiv
            "numbering": 1 if g.get("numbering") in (1, "1") else 0,
            "duskCatchUp": bool(g.get("duskCatchUp", True)),
            "liveToScene": bool(g.get("liveToScene")),
            "scenes": scenes,
            "funcs": [],
        }
        seen_f = set()
        for f in g.get("funcs") or []:
            if not isinstance(f, dict):
                continue
            fid = str(f.get("id") or "")
            if not fid or fid in seen_f:
                fid = new_id("f")
            seen_f.add(fid)
            typ = f.get("type") if f.get("type") in TYPES else "switch"
            trade = f.get("trade") if f.get("trade") in TRADES else "licht"
            season = bool(f.get("season")) if "season" in f else trade == "dachfenster"
            sv = []
            src = f.get("sv") if isinstance(f.get("sv"), list) else []
            for i in range(n):
                e = src[i] if i < len(src) and isinstance(src[i], dict) else {}
                v = to_num(e.get("v"))
                ne = {"en": bool(e.get("en")), "v": v if v is not None else 0}
                if typ == "blind" and e.get("m") == "move":
                    ne["m"] = "move"             # 1 Bit fahren (Langzeit) statt Position
                if typ == "rgbw":
                    ne["c"] = norm_color(e.get("c"))  # Farbe R, G, B, W in 0–100 %
                if typ == "heat":                     # Szene: Betriebsart (o, None = nicht senden) + Sollwert (v, nur bei sp)
                    if v is None:
                        ne["v"] = 21
                    ne["sp"] = bool(e.get("sp"))
                    ne["o"] = norm_hvac(e.get("o"))
                if season or "vw" in e:          # Winter-Zeile (Sommer = en/v)
                    vw = to_num(e.get("vw"))
                    ne.update({"ew": bool(e.get("ew")), "vw": vw if vw is not None else 0})
                    if typ == "blind" and e.get("mw") == "move":
                        ne["mw"] = "move"
                    if typ == "rgbw":
                        ne["cw"] = norm_color(e.get("cw") if e.get("cw") is not None else e.get("c"))
                    if typ == "heat":
                        if vw is None:
                            ne["vw"] = ne["v"]
                        ne["spw"] = bool(e.get("spw")) if "spw" in e else ne["sp"]
                        ne["ow"] = norm_hvac(e.get("ow")) if "ow" in e else ne["o"]
                sv.append(ne)
            nf = {"id": fid, "name": str(f.get("name") or "Funktion")[:60], "type": typ,
                  "key": norm_key(f.get("key")), "status": norm_key(f.get("status")),
                  "dusk": bool(f.get("dusk")), "sv": sv,
                  "trade": trade, "rain": bool(f.get("rain")),
                  "season": season}            # getrennte Werte für Sommer/Winter (Außentemperatur)
            tmin = to_num(f.get("tmin")) if f.get("tmin") not in (None, "", False) else None
            if tmin is not None:                     # v4.2: erst ab dieser Außentemperatur öffnen/einschalten
                nf["tmin"] = max(-40.0, min(60.0, float(tmin)))
            if typ in ("switch", "blind", "lock"):
                for k in ("lbl0", "lbl1"):
                    if f.get(k):
                        nf[k] = str(f.get(k))[:12]
            if typ == "blind":
                nf.update({"min": 0, "max": 100, "step": to_num(f.get("step")) or 1, "unit": "%",
                           "moveKey": norm_key(f.get("moveKey")),     # 1 Bit Auf/Ab (Langzeit)
                           "stopKey": norm_key(f.get("stopKey")),     # 1 Bit Stopp (Kurzzeit), nur „Aktuell“
                           "moveInv": bool(f.get("moveInv")),         # True: Auf = 1, Zu = 0
                           "posInv": bool(f.get("posInv"))})          # v4.2: Position-KO invertiert (KNX 0 % = offen), Seite zeigt 0 % = zu
            elif typ == "rgbw":
                nf.update({"min": 0, "max": 100, "step": 1, "unit": "%",
                           "chMax": 255 if to_num(f.get("chMax")) == 255 else 100})   # Kanäle 0–100 % oder 0–255
                for k in RGBW:
                    nf[k] = norm_key(f.get(k))
            elif typ == "heat":
                for k, d in (("min", 5), ("max", 30), ("step", 0.5)):
                    v = to_num(f.get(k))
                    nf[k] = v if v is not None else d
                nf["unit"] = "°C"
                for k in HEATK:
                    nf[k] = norm_key(f.get(k))
                nf["plan"] = norm_plan(f.get("plan"))
                # Freigabe: "scene" = nur Szenen, "plan" = nur Zeitprogramm (Szenen lassen die Heizung aus), "both" = beides
                ctl = f.get("ctl") if f.get("ctl") in ("scene", "plan", "both") else ("both" if nf["plan"]["on"] else "scene")
                nf["ctl"] = ctl
                nf["plan"]["on"] = ctl != "scene"
            elif typ in ("dim", "value"):
                for k, d in (("min", 0), ("max", 100), ("step", 1)):
                    v = to_num(f.get(k))
                    nf[k] = v if v is not None else d
                nf["unit"] = str(f.get("unit") if f.get("unit") is not None else ("%" if typ == "dim" else ""))[:10]
            ng["funcs"].append(nf)
        out["groups"].append(ng)
    if not out["groups"]:
        out["groups"].append(norm_config({"groups": [{"id": "g1", "name": "Szenen", "trigger": 1}]})["groups"][0])
    return out


# ====================================================================== KO-Gateway (WebSocket-Client)
class GatewayClient(object):
    """Minimaler WebSocket-Client (RFC 6455) für das KO-Gateway des HomeServers."""

    def __init__(self, module):
        self.m = module
        self.url = ""
        self.user = ""
        self.pw = ""
        self._sock = None
        self._send_lock = threading.Lock()
        self._stop = threading.Event()
        self._thread = None
        self.connected = False
        self.subscribed = set()
        self.msg = "nicht gestartet"
        self._tag = 0
        self._probes = []          # [(set(keys), dict result, Event)]
        self._plock = threading.Lock()
        self.log = collections.deque(maxlen=300)   # Debug: (Zeit, Richtung, Text)

    def dlog(self, d, text):
        self.log.append((time.time(), d, text[:400]))

    # ------------------------------------------------ Steuerung
    def start(self, url, user, pw):
        self.stop()
        self.url, self.user, self.pw = url, user, pw
        self._stop = threading.Event()
        self._thread = threading.Thread(target=self._run, args=(self._stop,), daemon=True)
        self._thread.start()

    def stop(self):
        self._stop.set()
        s = self._sock
        if s is not None:
            try:
                self._send_frame(0x8, struct.pack("!H", 1000))
            except Exception:
                pass
            try:
                s.close()
            except OSError:
                pass
        if self._thread is not None:
            self._thread.join(3.0)
        self._thread = None
        self._set_connected(False)

    # ------------------------------------------------ Senden
    def set_value(self, key, value):
        return self._send_json({"type": "call", "param": {"key": key, "method": "set", "value": fmt_val(value)},
                                "tag": self._next_tag("s")})

    def subscribe(self, keys):
        keys = [k for k in keys if k]
        ok = True
        for i in range(0, len(keys), 100):
            part = keys[i:i + 100]
            if self._send_json({"type": "subscribe", "param": {"keys": part}, "tag": self._next_tag("a")}):
                self.subscribed.update(part)
            else:
                ok = False
        return ok

    def probe(self, keys, timeout=4.0):
        keys = [norm_key(k) for k in keys if k][:40]
        res = {}
        ev = threading.Event()
        entry = (set(keys), res, ev)
        with self._plock:
            self._probes.append(entry)
        try:
            if not self.connected:
                return None
            if not self._send_json({"type": "subscribe", "param": {"keys": keys}, "tag": self._next_tag("p")}):
                return None
            end = time.time() + timeout
            while time.time() < end and len(res) < len(keys):
                ev.wait(0.2)
                ev.clear()
            return res
        finally:
            with self._plock:
                if entry in self._probes:
                    self._probes.remove(entry)

    def _next_tag(self, p):
        self._tag += 1
        return "%s%d" % (p, self._tag)

    def _send_json(self, obj):
        data = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        ok = self._send_frame(0x1, data)
        self.dlog("out" if ok else "err", ("=> " if ok else "nicht gesendet: ") + data.decode("utf-8", "replace"))
        return ok

    def _send_frame(self, opcode, payload):
        s = self._sock
        if s is None or not self.connected and opcode == 0x1:
            return False
        n = len(payload)
        head = bytearray([0x80 | opcode])
        if n < 126:
            head.append(0x80 | n)
        elif n < 65536:
            head.append(0x80 | 126)
            head += struct.pack("!H", n)
        else:
            head.append(0x80 | 127)
            head += struct.pack("!Q", n)
        mask = os.urandom(4)
        head += mask
        body = bytearray(payload)
        for i in range(n):
            body[i] ^= mask[i & 3]
        try:
            with self._send_lock:
                s.sendall(bytes(head) + bytes(body))
            return True
        except (OSError, ValueError) as e:
            self.msg = "Senden fehlgeschlagen: %s" % e
            try:
                s.close()
            except OSError:
                pass
            return False

    # ------------------------------------------------ Verbindung
    def _parse_url(self):
        u = self.url.strip() or "wss://127.0.0.1:443"
        if "://" not in u:
            u = "wss://" + u
        p = urllib.parse.urlsplit(u)
        tls = p.scheme in ("wss", "https")
        return p.hostname or "127.0.0.1", p.port or (443 if tls else 80), tls

    def _connect(self):
        host, port, tls = self._parse_url()
        raw = socket.create_connection((host, port), timeout=10)
        s = raw
        if tls:
            ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE          # HS-Zertifikat ist selbstsigniert
            s = ctx.wrap_socket(raw, server_hostname=host)
        auth = base64.b64encode(("%s:%s" % (self.user, self.pw)).encode("utf-8")).decode("ascii")
        key = base64.b64encode(os.urandom(16)).decode("ascii")
        req = ("GET /endpoints/ws?authorization=%s HTTP/1.1\r\n"
               "Host: %s:%d\r\n"
               "Upgrade: websocket\r\n"
               "Connection: Upgrade\r\n"
               "Sec-WebSocket-Key: %s\r\n"
               "Sec-WebSocket-Version: 13\r\n"
               "User-Agent: HSL3-14778/%s\r\n\r\n") % (urllib.parse.quote(auth, safe=""), host, port, key, VERSION)
        s.sendall(req.encode("ascii"))
        resp = b""
        while b"\r\n\r\n" not in resp:
            chunk = s.recv(1024)
            if not chunk:
                raise IOError("Gateway hat die Verbindung beim Handshake geschlossen")
            resp += chunk
            if len(resp) > 16384:
                raise IOError("Ungültige Antwort beim Handshake")
        head, rest = resp.split(b"\r\n\r\n", 1)
        first = head.split(b"\r\n", 1)[0].decode("latin-1")
        if " 101" not in first:
            if " 401" in first or " 403" in first:
                raise IOError("Anmeldung abgelehnt (%s) - Benutzer/Passwort E5/E6 pruefen" % first.strip())
            raise IOError("Kein WebSocket: %s" % first.strip())
        return s, rest

    def _run(self, stop):
        backoff = 1.0
        while not stop.is_set():
            try:
                self.msg = "verbinde mit %s:%d" % self._parse_url()[:2]
                self.m._gw_status()
                sock, buf = self._connect()
                sock.settimeout(1.0)
                self._sock = sock
                self.subscribed = set()
                self._set_connected(True)
                self.msg = "verbunden"
                backoff = 1.0
                self.dlog("in", "verbunden mit %s:%d" % self._parse_url()[:2])
                self.subscribe(sorted(self.m.wanted_keys()))
                self._loop(sock, buf, stop)
            except Exception as e:
                self.msg = "Fehler: %s" % (e,)
                if not stop.is_set():
                    self.dlog("err", self.msg + " - naechster Versuch in %d s" % backoff)
            finally:
                self._set_connected(False)
                s, self._sock = self._sock, None
                if s is not None:
                    try:
                        s.close()
                    except OSError:
                        pass
            if stop.wait(backoff):
                break
            backoff = min(backoff * 2, 30.0)

    def _set_connected(self, on):
        if self.connected != on:
            self.connected = on
            self.m._gw_status()

    def _loop(self, sock, buf, stop):
        buf = bytearray(buf)
        frags = bytearray()
        last_ping = t0 = time.time()
        while not stop.is_set():
            # fehlende Abos nachholen (neue Funktionen)
            missing = self.m.wanted_keys() - self.subscribed
            if missing:
                self.subscribe(sorted(missing))
            if time.time() - last_ping > 30:
                self._send_frame(0x9, b"hs")
                last_ping = time.time()
            try:
                chunk = sock.recv(65536)
                if not chunk:
                    raise IOError("Verbindung vom Gateway geschlossen" + (
                        " - direkt nach der Anmeldung: Benutzer/Passwort oder Endpunkt-Rechte pruefen"
                        if time.time() - t0 < 5 else ""))
                buf += chunk
            except socket.timeout:
                pass
            while True:
                fr = self._take_frame(buf)
                if fr is None:
                    break
                fin, op, payload = fr
                if op == 0x8:
                    cc = struct.unpack("!H", payload[:2])[0] if len(payload) >= 2 else 0
                    hint = {1008: " - Benutzer/Passwort oder Endpunkt-Rechte pruefen",
                            1006: " - Benutzer/Passwort oder Endpunkt-Rechte pruefen",
                            4001: " - Anmeldung abgelehnt"}.get(cc, "")
                    raise IOError("Gateway beendet die Verbindung (Close %s)%s" % (cc or "-", hint))
                if op == 0x9:
                    self._send_frame(0xA, payload)
                    continue
                if op == 0xA:
                    continue
                if op in (0x1, 0x2):
                    frags = bytearray(payload)
                elif op == 0x0:
                    frags += payload
                if fin:
                    data, frags = bytes(frags), bytearray()
                    self.dlog("in", "<= " + data.decode("utf-8", "replace"))
                    try:
                        msg = json.loads(data.decode("utf-8", "replace"))
                    except ValueError:
                        continue
                    try:
                        self._handle(msg)
                    except Exception as e:
                        self.m.debug.log("Gateway-Nachricht: %r" % (e,))

    @staticmethod
    def _take_frame(buf):
        if len(buf) < 2:
            return None
        b0, b1 = buf[0], buf[1]
        n = b1 & 0x7F
        pos = 2
        if n == 126:
            if len(buf) < 4:
                return None
            n = struct.unpack("!H", bytes(buf[2:4]))[0]
            pos = 4
        elif n == 127:
            if len(buf) < 10:
                return None
            n = struct.unpack("!Q", bytes(buf[2:10]))[0]
            pos = 10
        mask = None
        if b1 & 0x80:
            if len(buf) < pos + 4:
                return None
            mask = bytes(buf[pos:pos + 4])
            pos += 4
        if len(buf) < pos + n:
            return None
        payload = bytearray(buf[pos:pos + n])
        if mask:
            for i in range(n):
                payload[i] ^= mask[i & 3]
        del buf[:pos + n]
        return bool(b0 & 0x80), b0 & 0x0F, bytes(payload)

    # ------------------------------------------------ Empfang
    def _handle(self, m):
        if not isinstance(m, dict):
            return
        data = m.get("data") if isinstance(m.get("data"), dict) else {}
        items = data.get("items")
        if isinstance(items, list):                           # Antwort auf subscribe
            for it in items:
                if not isinstance(it, dict):
                    continue
                key = norm_key(it.get("key") if it.get("key") is not None else it.get("uid"))
                if not key:
                    continue
                code = it.get("code", 0)
                probed = False
                with self._plock:
                    for keys, res, ev in self._probes:
                        if key in keys:
                            res[key] = code
                            probed = True
                            ev.set()
                if probed and key not in self.m.wanted_keys(all_keys=True):
                    continue                      # nur Test der Schreibweise, kein Abo der Seite
                if code not in (0, None):
                    self.subscribed.discard(key)
                    self.m._key_error(key, code)
                    continue
                d = it.get("data") if isinstance(it.get("data"), dict) else {}
                v = d.get("value", it.get("value"))
                if v is not None:
                    self.m.on_value(key, v, initial=True)
            return
        code = m.get("code")
        if code not in (None, 0):
            rq = m.get("request") if isinstance(m.get("request"), dict) else {}
            p = rq.get("param") if isinstance(rq.get("param"), dict) else {}
            k = rq.get("key") or p.get("key") or ""
            if k:
                self.m._key_error(norm_key(k), code)
            else:
                self.m.debug.log("Gateway-Fehler %s: %s" % (code, json.dumps(m)[:200]))
            return
        sub = m.get("subscription") if isinstance(m.get("subscription"), dict) else {}
        rq = m.get("request") if isinstance(m.get("request"), dict) else {}
        key = sub.get("key") or data.get("key") or data.get("uid")
        if not key and m.get("type") in ("push", "event"):
            key = rq.get("key")
        if key and "value" in data:
            self.m.on_value(norm_key(key), data["value"], initial=False)


# ====================================================================== Baustein
class LogicModule:
    def __init__(self, hsl3):
        self.fw = hsl3
        self.debug = self.fw.create_debug_section()
        self._lock = threading.RLock()
        self._cond = threading.Condition(self._lock)
        self.base_path = "szenen"
        self.port = 8093
        self.port_missing = False
        self.key = ""
        self.gw_cfg = ("", "", "")
        self.gw_share = False
        self.config = norm_config(None)
        self.rev = 0
        self.active = {}             # gid -> Szene (1..n) oder 0
        self.values = {}             # KO-Schlüssel -> Wert (vom Gateway)
        self.key_errors = {}         # KO-Schlüssel -> Code
        self.dark_input = False
        self.rain_input = False
        self.temp_input = None       # None = unbekannt
        self.pending = {}            # (gid, fid) -> Wert, wartet auf Bedingung (nachholen)
        self.rain_hold = {}          # (gid, fid) -> Wert, wird nach Regen wiederhergestellt
        self._raining = False        # letzter Regenzustand
        self._rain_timer = None
        self.summer = None           # True = Sommer, False = Winter, None = Temperatur unbekannt
        self.sw = {"t": [None, None, None], "d": ["", "", ""]}   # Messwerte 7/14/22 Uhr + Tag (remanent)
        self._sw_out = None
        self.hp = {}                 # Zeitprogramm Heizung: fid -> {"k": Tag Kommen ausgeführt, "g": Tag Gehen}
        self._tavg = collections.deque()   # (Zeit, Außentemperatur) der letzten 3 h für den Vorlauf
        self._sw_thread = None
        self._now = time.localtime
        self._last_trig = {}         # gid -> (Wert, Zeit, Quelle)
        self.seq = 1
        self.last_event = ""
        self.gw = GatewayClient(self)
        self._tl = threading.local()
        self._sq = collections.OrderedDict()   # v4.3: Sendewarteschlange KO -> Wert (neuerer Wert ersetzt älteren)
        self._sq_cv = threading.Condition()
        self._sq_thread = None
        self._httpd = self._stop = self._thread = None
        self._page = None

    # ------------------------------------------------------------ Lebenszyklus
    def on_init(self, inputs, store):
        self._read_inputs(inputs)
        try:
            data = unpack([store.value("c%02d" % k) for k in range(1, CFG_STORES + 1)])
            if isinstance(data, dict) and isinstance(data.get("config"), dict):
                self.config = norm_config(data["config"])
                self.rev = int(data.get("rev") or 0)
        except Exception as e:
            self.debug.log("Einrichtung unlesbar: %r" % (e,))
        try:
            act = json.loads(self.fw_text(store.value("act")) or "{}")
            if isinstance(act, dict) and "a" in act:
                self.active = dict((str(k), int(v)) for k, v in (act.get("a") or {}).items())
                self.rain_hold = dict(((str(h[0]), str(h[1])), tuple([float(h[2]), str(h[3]) if len(h) > 3 else "pos"] + list(h[4:5])))
                                      for h in act.get("h") or [])
                self._raining = bool(act.get("r"))
            elif isinstance(act, dict):
                self.active = dict((str(k), int(v)) for k, v in act.items())
        except Exception as e:
            self.debug.log("Aktive Szenen unlesbar: %r" % (e,))
        try:
            g = json.loads(self.fw_text(store.value("gw")) or "{}")
            self.gw_cfg = (str(g.get("url") or ""), str(g.get("user") or ""),
                           base64.b64decode(g.get("pw") or "").decode("utf-8") if g.get("pw") else "")
            self.gw_share = bool(g.get("share"))
        except Exception as e:
            self.debug.log("Gateway-Zugang unlesbar: %r" % (e,))
        self.dark_input = self._num(inputs.value("dusk"), 0) >= 1
        self.rain_input = self._num(inputs.value("rain"), 0) >= 1
        self.temp_input = self._temp(inputs.value("temp"))
        try:
            sw = json.loads(self.fw_text(store.value("sw")) or "{}")
            if isinstance(sw.get("t"), list) and len(sw["t"]) == 3:
                self.sw = {"t": [to_num(x) for x in sw["t"]], "d": [str(x or "") for x in (sw.get("d") or ["", "", ""])][:3]}
        except Exception as e:
            self.debug.log("Sommer/Winter-Werte unlesbar: %r" % (e,))
        try:
            hp = json.loads(self.fw_text(store.value("hp")) or "{}")
            self.hp = dict((str(k), dict(v)) for k, v in hp.items() if isinstance(v, dict))
        except Exception as e:
            self.debug.log("Zeitprogramm-Status unlesbar: %r" % (e,))
        self._update_season()
        self._rebuild_pending()
        if not self.config["rainKey"]:
            self._check_rain()                   # Regen über E13: sofort auswerten (auch Ende während Neustart)
        self._publish_outputs(force=True)
        self._start_server()
        self._start_gw()
        if self._sw_thread is None:
            self._sw_thread = threading.Thread(target=self._sw_loop, daemon=True)
            self._sw_thread.start()

    # ------------------------------------------------------------ Sommer/Winter (Tagesmittel)
    def _sw_loop(self):
        while True:
            try:
                self._sw_check()
            except Exception as e:
                self.debug.log("Sommer/Winter: %r" % (e,))
            try:
                self._plan_check()
            except Exception as e:
                self.debug.log("Zeitprogramm: %r" % (e,))
            time.sleep(20)

    # ------------------------------------------------------------ Zeitprogramm Heizung
    def day_free(self, d):
        """(frei?, Name) für einen Tag: manuell gesetzt > Feiertag."""
        cal = self.config["cal"]
        m = cal["days"].get(d.isoformat())
        name = holidays(d.year, cal["state"], cal["mh"]).get(d)
        if m == 1:
            return True, name or "frei (manuell)"
        if m == 0:
            return False, "Arbeitstag (manuell)"
        return (name is not None), name

    def is_bridge(self, d, wd):
        """Brückentag: einzelner Arbeitstag zwischen einem Feiertag und einem freien Tag (Wochenende, Feiertag, manuell frei)."""
        cal = self.config["cal"]
        if not cal.get("bridge") or d.weekday() >= wd:
            return False
        hol = lambda x: x in holidays(x.year, cal["state"], cal["mh"])
        if hol(d):
            return False
        free = lambda x: cal["days"].get(x.isoformat()) == 1 or x.weekday() >= wd or hol(x)
        one = datetime.timedelta(days=1)
        a, b = d - one, d + one
        return free(a) and free(b) and (hol(a) or hol(b))

    def is_workday(self, d, wd):
        m = self.config["cal"]["days"].get(d.isoformat())
        if m is not None:
            return m == 0
        return d.weekday() < wd and not self.day_free(d)[0] and not self.is_bridge(d, wd)

    def outdoor_avg(self, sample=False):
        """Außentemperatur gemittelt über die letzten 3 Stunden (für den Vorlauf)."""
        now, t = time.time(), self.temp()
        with self._lock:
            if sample and t is not None:
                self._tavg.append((now, float(t)))
            while self._tavg and self._tavg[0][0] < now - 3 * 3600:
                self._tavg.popleft()
            if self._tavg:
                return sum(x[1] for x in self._tavg) / len(self._tavg)
        return t

    def pre_row(self, p, d):
        """Vorlauf-Zeile für den Tag: Wochentag, bzw. Montag nach freien Tagen (z. B. Dienstag nach Ostermontag)."""
        i = d.weekday()
        if i > 5:
            return 0                                   # Sonntag als Arbeitstag: wie Montag
        if i != 0 and p.get("af") and not self.is_workday(d - datetime.timedelta(days=1), p["wd"]):
            return 0
        return i

    def _plan_times(self, p, d, T):
        kh, km = [int(x) for x in p["k"].split(":")]
        gh, gm = [int(x) for x in p["g"].split(":")]
        come = datetime.datetime(d.year, d.month, d.day, kh, km)
        go = datetime.datetime(d.year, d.month, d.day, gh, gm)
        pre = pre_minutes(p["pre"][self.pre_row(p, d)], T)
        return come - datetime.timedelta(minutes=pre), come, go, pre

    def plan_info(self, f, now=None, T=None):
        """Nächste Aktion des Zeitprogramms (für die Anzeige)."""
        p = f.get("plan") or {}
        if not p.get("on"):
            return None
        now = now or datetime.datetime(*self._now()[:6])
        for i in range(0, 15):
            d = now.date() + datetime.timedelta(days=i)
            if not self.is_workday(d, p["wd"]):
                continue
            start, come, go, pre = self._plan_times(p, d, T)
            if now < start:
                return {"next": "k", "at": start.strftime("%Y-%m-%dT%H:%M"), "come": come.strftime("%H:%M"), "pre": int(round(pre))}
            if now < go:
                return {"next": "g", "at": go.strftime("%Y-%m-%dT%H:%M"), "pre": int(round(pre))}
        return {"next": None}

    def _plan_check(self):
        """Kommen (minus Vorlauf) und Gehen an Arbeitstagen ausführen – je Heizungsfunktion, auch nach Neustart."""
        now = datetime.datetime(*self._now()[:6])
        T = self.outdoor_avg(sample=True)
        sends, events = [], []
        with self._lock:
            for g in self.config["groups"]:
                for f in g["funcs"]:
                    p = f.get("plan")
                    if f["type"] != "heat" or not p or not p["on"] or not self.can_send(f):
                        continue
                    st = self.hp.setdefault(f["id"], {})
                    for d in (now.date(), now.date() + datetime.timedelta(days=1)):
                        if not self.is_workday(d, p["wd"]):
                            continue
                        start, come, go, pre = self._plan_times(p, d, T)
                        ds = d.isoformat()
                        if start <= now < go and st.get("k") != ds:
                            st["k"] = ds
                            sends.append((f, (p["kv"] if p["ksp"] else None, "heat", p["ko"])))
                            events.append("%s: Kommen (Vorlauf %d min, %s C)" % (f["name"], pre, "?" if T is None else "%.1f" % T))
                    d = now.date()
                    if self.is_workday(d, p["wd"]):
                        start, come, go, pre = self._plan_times(p, d, T)
                        if now >= go and st.get("g") != d.isoformat() and go > come:
                            st["g"] = d.isoformat()
                            sends.append((f, (p["gv"] if p["gsp"] else None, "heat", p["go"])))
                            events.append("%s: Gehen" % f["name"])
            if events:
                self.last_event = "Zeitprogramm " + "; ".join(events)
                data = json.dumps(self.hp, separators=(",", ":"))
        if events:
            self._send_all(sends)
            self.fw.run_in_context(lambda: self.fw.set_store("hp", data.encode("ascii")), ())
            self.debug.set("Zeitprogramm", self.last_event)
            self._bump()
        return len(events)

    def _sw_check(self):
        """Um 7, 14 und 22 Uhr (innerhalb der Stunde, einmal je Tag) die Außentemperatur speichern."""
        tm = self._now()
        if tm.tm_hour not in SEASON_HOURS:
            return False
        i = SEASON_HOURS.index(tm.tm_hour)
        day = "%04d-%02d-%02d" % (tm.tm_year, tm.tm_mon, tm.tm_mday)
        t = self.temp()
        with self._lock:
            if self.sw["d"][i] == day or t is None:
                return False
            self.sw["t"][i] = round(float(t), 2)
            self.sw["d"][i] = day
            self.last_event = "Sommer/Winter: %d Uhr %.1f C gespeichert" % (SEASON_HOURS[i], t)
        self.fw.run_in_context(self._sw_ctx, ())
        return True

    def _sw_ctx(self):
        with self._lock:
            data = json.dumps(self.sw, separators=(",", ":"))
        self.fw.set_store("sw", data.encode("ascii"))
        self._update_season(apply=True)
        self._bump()

    def season_mean(self):
        """(T7 + T14 + T22 + T22) / 4. Fehlende Messwerte (erste Tage) durch die aktuelle Temperatur ersetzt."""
        t = self.temp()
        v = [x if x is not None else t for x in self.sw["t"]]
        if any(x is None for x in v):
            return None
        return (v[0] + v[1] + v[2] + v[2]) / 4.0

    def _season_outputs_ctx(self):
        with self._lock:
            m, t, sm = self.season_mean(), self.temp(), self.summer is True
            f = lambda x, d: "-" if x is None else (("%." + str(d) + "f") % x)
            f1 = lambda x: "-" if x is None else ("%.1f" % x).rstrip("0").rstrip(".")
            dbg = "T1:%s T2:%s T3:%s S:%s At:%s" % (f1(self.sw["t"][0]), f1(self.sw["t"][1]), f1(self.sw["t"][2]), f(m, 2), f(t, 1))
        out = (sm, dbg)
        if out == self._sw_out:
            return
        if self._sw_out is None or self._sw_out[0] != sm:
            self.fw.set_output("summer", 1.0 if sm else 0.0)          # A13
            self.fw.set_output("winter", 0.0 if sm else 1.0)          # A14
            self.fw.set_output("season_sym", 1.0 if sm else 2.0)      # A15 Symbol: 1 = Sommer, 2 = Winter
            self.fw.set_output("season_txt", b"Sommer" if sm else b"Winter")   # A16
        self.fw.set_output("season_dbg", dbg.encode("ascii", "replace"))   # A17
        self._sw_out = out

    def on_calc(self, inputs):
        old_srv = (self.base_path, self.port)
        self._read_inputs(inputs)
        restart = False
        if inputs.changed("restart"):
            restart = self._num(inputs.value("restart"), 0) == 1
            self._publish_outputs(force=True)
        if restart or (self.base_path, self.port) != old_srv:
            self._start_server()
        if restart:
            self._start_gw()
        cond = False
        if inputs.changed("dusk"):
            self.dark_input = self._num(inputs.value("dusk"), 0) >= 1
            cond = True
        if inputs.changed("temp"):
            self.temp_input = self._temp(inputs.value("temp"))
            self._update_season(apply=True)
            cond = True
        if inputs.changed("rain"):
            self.rain_input = self._num(inputs.value("rain"), 0) >= 1
            self._check_rain()
        if cond:
            self._bump()
            self._conditions_changed()
        g = self.io_group()
        if g is not None:
            if inputs.changed("scene"):                     # E5 DPT 17.001
                v = self._num(inputs.value("scene"), None)
                if v is not None:
                    self.trigger(g["id"], int(v), "E5")
            for i in range(1, N_BITS + 1):                  # E6–E13 Szene 1–8 (1 Bit, 1 = aufrufen)
                ident = "s%d" % i
                if inputs.changed(ident) and self._num(inputs.value(ident), 0) >= 1:
                    self.call_scene(g["id"], i, False, "E%d" % (5 + i))

    def io_group(self):
        """Gruppe, die über die Baustein-Ein- und Ausgänge läuft (erste mit „Baustein-Eingänge“)."""
        for g in self.config["groups"]:
            if g["trigger"]:
                return g
        return None

    def _read_inputs(self, inputs):
        self.base_path = self._text(inputs.value("base_path")).strip("/ ") or "szenen"
        self.port = int(self._num(inputs.value("destination_port"), 8093) or 0)
        self.port_missing = self.port <= 0
        if self.port_missing:
            self.port = 8093
        self.key = self._text(inputs.value("key")).strip()
        self.debug.set("Schutz", "Schluessel gesetzt" if self.key else "OHNE Schluessel")

    def _temp(self, v):
        t = self._num(v, None)
        return None if t is None or t <= -99 else t

    # ------------------------------------------------------------ Gateway
    def _start_gw(self):
        url, user, pw = self.gw_cfg
        url = url or "wss://127.0.0.1:443"
        with self._lock:
            self.key_errors = {}
        if not user:
            self.gw.stop()
            self.gw.msg = "Kein Gateway-Zugang - auf der Webseite unter Verbindung eintragen"
            self._gw_status()
            return
        self.gw.start(url, user, pw)

    def wanted_keys(self, all_keys=False):
        with self._lock:
            ks = set(k for k in (self.config["duskKey"], self.config["rainKey"], self.config["tempKey"]) if k)
            for g in self.config["groups"]:
                if g["triggerKey"]:
                    ks.add(g["triggerKey"])
                for f in g["funcs"]:
                    ks.update(func_keys(f))
            return ks if all_keys else ks - set(self.key_errors)

    def _key_error(self, key, code):
        with self._lock:
            self.key_errors[key] = code
            self.last_event = "KO %s: Gateway-Code %s" % (key, code)
        self.debug.log("KO %s nicht verfuegbar (Code %s)" % (key, code))
        self._bump()

    def on_value(self, key, value, initial):
        """Wert vom Gateway (Abo-Antwort oder Änderung). Läuft im Gateway-Thread."""
        n = to_num(value)
        v = n if n is not None else value
        triggers = []
        cond = rain = False
        with self._lock:
            self.values[key] = v
            for g in self.config["groups"]:
                if not initial and g["triggerKey"] == key:
                    triggers.append(g["id"])
            cond = key in (self.config["duskKey"], self.config["tempKey"])
            rain = key == self.config["rainKey"]
        if key == self.config["tempKey"]:
            self._update_season(apply=not initial)
        self._bump()
        for gid in triggers:
            self.trigger(gid, int(n or 0), "KO " + key)
        if rain:
            self._check_rain()
        if cond:
            self._conditions_changed()

    def _gw_status(self):
        self.fw.run_in_context(self._gw_status_ctx, ())
        self._bump()

    def _gw_status_ctx(self):
        self._out("gw_ok", 1.0 if self.gw.connected else 0.0)
        self.debug.set("KO-Gateway", self.gw.msg)
        if self.gw.connected:
            self._status("Bereit: /%s/ (Port %d), Gateway verbunden%s" %
                         (self.base_path, self.port, "" if self.key else " - OHNE Schluessel"))
        elif self._httpd is not None:
            self._status("Gateway: %s" % self.gw.msg)

    # ------------------------------------------------------------ Bedingungen
    def _group(self, gid):
        for g in self.config["groups"]:
            if g["id"] == gid:
                return g
        return None

    def _func(self, g, fid):
        for f in g["funcs"]:
            if f["id"] == fid:
                return f
        return None

    # Sensoren gelten für alle Gruppen (g bleibt für spätere Erweiterungen im Aufruf)
    def is_dark(self, g=None):
        k = self.config["duskKey"]
        return (to_num(self.values.get(k)) or 0) >= 1 if k else self.dark_input

    def is_raining(self, g=None):
        k = self.config["rainKey"]
        return (to_num(self.values.get(k)) or 0) >= 1 if k else self.rain_input

    def temp(self, g=None):
        k = self.config["tempKey"]
        return to_num(self.values.get(k)) if k else self.temp_input

    def _update_season(self, apply=False):
        """Sommer/Winter in Anlehnung an DIN: Tagesmittel (T7 + T14 + 2*T22) / 4 >= Grenze -> Sommer.
        Sind alle drei Messwerte da, ändert sich die Jahreszeit nur zu den Messzeitpunkten.
        apply=True: bei Wechsel die Sommer/Winter-Funktionen der aktiven Szenen umstellen (mit „Nachholen“)."""
        lim = self.config["tempLimit"]
        sends = []
        with self._lock:
            t = m = self.season_mean()
            old = self.summer
            self.summer = None if m is None else m >= lim
            self.fw.run_in_context(self._season_outputs_ctx, ())   # A13–A17 (nur bei Änderung gesendet)
            if not apply or (old is True) == (self.summer is True):
                return
            for g in self.config["groups"]:
                n = self.active.get(g["id"], 0)
                if not g["duskCatchUp"] or not 1 <= n <= len(g["scenes"]):
                    continue
                for f in g["funcs"]:
                    if not f.get("season") or not self.can_send(f):
                        continue
                    en, v = self.entry(f, n)
                    k = (g["id"], f["id"])
                    self.pending.pop(k, None)
                    if not en:
                        continue
                    r = self.blocked(g, f, v)
                    if r:
                        self._defer(g, f, v, r)
                    else:
                        self.rain_hold.pop(k, None)
                        sends.append((f, v))
            self.last_event = "Jahreszeit: %s (Tagesmittel %s) - %d Werte der aktiven Szenen umgestellt" % (
                "Sommer" if self.summer else "Winter", "%.2f C" % t if t is not None else "?", len(sends))
        self._send_all(sends)
        self._save_active_async()
        self._bump()

    def blocked(self, g, f, v):
        """Gründe, warum der Wert jetzt nicht gesendet wird. Bedingungen gelten nur für Werte > 0
        (Licht ein, Rollo zu, Fenster/Tor auf) – Aus-/Schließbefehle gehen immer durch."""
        if isinstance(v, (tuple, list)):
            v = v[0]
        if (to_num(v) or 0) <= 0:
            return []
        r = []
        if f.get("dusk") and not self.is_dark(g):
            r.append("Daemmerung")
        if f.get("rain") and self.is_raining(g):
            r.append("Regen")
        if f.get("tmin") is not None:
            t = self.temp(g)
            if t is None or t < f["tmin"]:      # unbekannte Temperatur: sicherheitshalber nicht öffnen
                r.append("Temperatur")
        return r

    # ------------------------------------------------------------ Sommer/Winter-Zeilen
    def line(self, f):
        """"w" = Winter-Zeile gilt (auch bei unbekannter Temperatur), "s" = Sommer bzw. einzige Zeile."""
        return "w" if f.get("season") and self.summer is not True else "s"

    def entry(self, f, n, line=None):
        """(Freigabe, Befehl) der gültigen Zeile; Befehl = (Wert, "pos"|"move")."""
        e = f["sv"][n - 1]
        if f["type"] == "heat":
            w = (line or self.line(f)) == "w"
            if f.get("ctl") == "plan":                 # Freigabe nach Zeitprogramm: Szenen senden nichts
                return False, (None, "heat", None)
            en = bool(e.get("ew")) if w else e["en"]
            sp, v, o = (e.get("spw"), e.get("vw"), e.get("ow")) if w else (e.get("sp"), e.get("v"), e.get("o"))
            return en, (v if sp else None, "heat", o)
        if f["type"] == "rgbw":
            if (line or self.line(f)) == "w":
                return bool(e.get("ew")), (e.get("vw", 0), "rgbw", e.get("cw") or e.get("c"))
            return e["en"], (e["v"], "rgbw", e.get("c"))
        if (line or self.line(f)) == "w":
            return bool(e.get("ew")), (e.get("vw", 0), e.get("mw") or "pos")
        return e["en"], (e["v"], e.get("m") or "pos")

    @staticmethod
    def can_send(f):
        return bool(f["key"] or f.get("moveKey") or f.get("modeKey") or any(f.get(k) for k in RGBW))

    @staticmethod
    def cmd_to_ko(f, cmd):
        """Befehl → Liste [(KO, Wert), …].
        Fahren: Rollo 100 % = zu, Dachfenster/Tor 0 % = zu; KNX Langzeit Auf = 0, Ab/Zu = 1 (moveInv tauscht).
        RGBW: erst R, G, B, W (0–100 % bzw. 0–255), dann Helligkeit 0–100 %."""
        if not isinstance(cmd, (tuple, list)):
            cmd = (cmd, "pos")
        v, m = cmd[0], cmd[1]
        if m == "stop":
            return [(f["stopKey"], 1)] if f.get("stopKey") else []
        if m == "heat" or f["type"] == "heat":          # erst Betriebsart, dann Sollwert
            o = cmd[2] if len(cmd) > 2 else None
            out = []
            if o is not None and f.get("modeKey"):
                out.append((f["modeKey"], int(o)))
            if v is not None and f["key"]:
                out.append((f["key"], v))
            return out
        if m == "rgbw" or f["type"] == "rgbw":
            c = norm_color(cmd[2] if len(cmd) > 2 else None)
            out = []
            for k, x in zip(RGBW, c):
                if f.get(k):
                    out.append((f[k], int(x * 255 / 100.0 + 0.5) if f.get("chMax") == 255 else int(x + 0.5)))
            if f["key"]:
                out.append((f["key"], v))
            return out
        if (m == "move" or not f["key"]) and f.get("moveKey"):
            to_zu = ((to_num(v) or 0) >= 50) == (f.get("trade") == "rollo")
            bit = 1 if to_zu else 0
            if f.get("moveInv"):
                bit ^= 1
            return [(f["moveKey"], bit)]
        if f["key"] and f.get("posInv") and f["type"] == "blind" and to_num(v) is not None:
            v = 100 - to_num(v)                     # v4.2: Position invertiert senden
        return [(f["key"], v)] if f["key"] else []

    @staticmethod
    def pos_in(f, x):
        """Rückmeldung in die Logik der Seite umrechnen (Position invertiert)."""
        if x is not None and f.get("posInv") and f["type"] == "blind":
            return 100 - x
        return x

    def current_color(self, f):
        """Aktuelle Farbe aus den R/G/B/W-KOs (0–100 %)."""
        out = []
        for k in RGBW:
            x = to_num(self.values.get(f.get(k))) if f.get(k) else None
            if x is not None and f.get("chMax") == 255:
                x = x / 2.55
            out.append(round(x, 1) if x is not None else 0)
        return norm_color(out)

    def _defer(self, g, f, v, reasons):
        """Blockierten Wert merken: Regen → nach Regen wiederherstellen, sonst ggf. nachholen."""
        k = (g["id"], f["id"])
        if "Regen" in reasons and f.get("rain"):
            self.rain_hold[k] = v
            self.pending.pop(k, None)
        elif g["duskCatchUp"]:
            self.pending[k] = v
        else:
            self.pending.pop(k, None)

    def _rebuild_pending(self):
        """Zurückgestellte Werte der aktiven Szenen neu ermitteln (nach Start oder Änderung der Einrichtung)."""
        with self._lock:
            self.pending = {}
            for g in self.config["groups"]:
                n = self.active.get(g["id"], 0)
                if not g["duskCatchUp"] or not 1 <= n <= len(g["scenes"]):
                    continue
                for f in g["funcs"]:
                    en, v = self.entry(f, n)
                    if en and self.can_send(f) and (g["id"], f["id"]) not in self.rain_hold:
                        r = self.blocked(g, f, v)
                        if r and not ("Regen" in r and f.get("rain")):
                            self.pending[(g["id"], f["id"])] = v

    def _conditions_changed(self):
        """Dämmerung/Temperatur geändert: wartende Werte senden, deren Bedingungen jetzt erfüllt sind."""
        sends = []
        with self._lock:
            for (gid, fid), v in list(self.pending.items()):
                g = self._group(gid)
                f = self._func(g, fid) if g else None
                if f is None:
                    self.pending.pop((gid, fid), None)
                    continue
                r = self.blocked(g, f, v)
                if not r:
                    self.pending.pop((gid, fid), None)
                    sends.append((f, v))
                elif "Regen" in r and f.get("rain"):
                    self.pending.pop((gid, fid), None)
                    self.rain_hold[(gid, fid)] = v
            if sends:
                self.last_event = "Bedingung erfuellt: %d Werte nachgeholt" % len(sends)
        if sends:
            self._send_all(sends)
            self._bump()

    def _check_rain(self):
        """Regen beginnt: Stellungen der Regen-Funktionen merken (remanent).
        Regen endet (auch während eines Neustarts): nach Verzögerung wiederherstellen."""
        with self._lock:
            now = self.is_raining()
            was, self._raining = self._raining, now
            if now and not was:
                if self._rain_timer is not None:
                    self._rain_timer.cancel()
                    self._rain_timer = None
                n = 0
                for g in self.config["groups"]:
                    for f in g["funcs"]:
                        if not f.get("rain"):
                            continue
                        k = (g["id"], f["id"])
                        cur = self.pos_in(f, to_num(self.values.get(f["status"] or f["key"])))
                        if k not in self.rain_hold and cur is not None and cur > 0:
                            self.rain_hold[k] = (cur, "pos") if f["key"] else (100 if f.get("trade") != "rollo" else 0, "move")
                            n += 1
                self.last_event = "Regen - %d Stellungen gemerkt" % n
            elif not now and self.rain_hold and self._rain_timer is None:
                delay = self.config["rainDelay"] * 60 if was else 5
                self._start_rain_timer(delay)
                self.last_event = "Regen vorbei - Wiederherstellung in %s" % (
                    "%d min" % (delay // 60) if delay >= 60 else "%d s" % delay)
        self._save_active_async()
        self._bump()

    def _start_rain_timer(self, delay):
        tm = threading.Timer(delay, self._rain_restore)
        tm.daemon = True
        self._rain_timer = tm
        tm.start()

    def _rain_restore(self):
        sends = []
        with self._lock:
            self._rain_timer = None
            if self.is_raining() or not self.rain_hold:
                return
            if not self.gw.connected:              # z. B. kurz nach dem Neustart: später erneut
                self._start_rain_timer(5)
                return
            for (gid, fid), v in list(self.rain_hold.items()):
                self.rain_hold.pop((gid, fid))
                g = self._group(gid)
                f = self._func(g, fid) if g else None
                if f is None or not self.can_send(f):
                    continue
                r = self.blocked(g, f, v)
                if not r:
                    sends.append((f, v))
                elif g["duskCatchUp"]:
                    self.pending[(gid, fid)] = v
            self.last_event = "Nach Regen %d Stellungen wiederhergestellt" % len(sends)
        self._send_all(sends)
        self._save_active_async()
        self._bump()

    # ------------------------------------------------------------ Szenen
    def trigger(self, gid, raw, source):
        """Szenenwert auswerten: DPT 17.001 Bit 0–5 = 0–63 = Szene 1–64 (Bit 6/7 reserviert),
        bzw. bei Nummerierung „1 = Szene 1“: 1–64 = Szene 1–64, 0 = keine Szene.
        Kommt derselbe Wert innerhalb 1 s über Eingang UND Szenen-KO, zählt er nur einmal."""
        with self._lock:
            g = self._group(gid)
            if g is None:
                return
            now = time.time()
            last = self._last_trig.get(gid)
            kind = "KO" if source.startswith("KO") else "E"
            if last and last[0] == raw and last[2] != kind and now - last[1] < 1.0:
                return
            self._last_trig[gid] = (raw, now, kind)
            learn = False
            if g["numbering"] == 0:
                n = (raw & 0x3F) + 1
            else:
                n = raw & 0x7F
        self.call_scene(gid, n, learn, source)

    def call_scene(self, gid, n, learn=False, source="Webseite"):
        sends = []
        with self._lock:
            g = self._group(gid)
            if g is None:
                return {"ok": False, "error": "Gruppe unbekannt"}
            count = len(g["scenes"])
            if n == 0 and not learn:
                self.active[gid] = 0
                for k in [k for k in self.pending if k[0] == gid]:
                    self.pending.pop(k)
                self.last_event = "%s: keine Szene aktiv (%s)" % (g["name"], source)
            elif not 1 <= n <= count:
                self.last_event = "%s: Szene %d gibt es nicht (%s)" % (g["name"], n, source)
                self._bump()
                return {"ok": False, "error": "Szene %d gibt es nicht" % n}
            elif learn:
                taken = 0
                for f in g["funcs"]:
                    if f["type"] == "heat":
                        w = self.line(f) == "w"
                        sp = to_num(self.values.get(f.get("setStatus") or f["key"])) if (f.get("setStatus") or f["key"]) else None
                        o = norm_hvac(self.values.get(f.get("modeStatus") or f.get("modeKey"))) if (f.get("modeStatus") or f.get("modeKey")) else None
                        e = f["sv"][n - 1]
                        if sp is not None and f["key"]:
                            e["vw" if w else "v"], e["spw" if w else "sp"] = sp, True
                        if o is not None and f.get("modeKey"):
                            e["ow" if w else "o"] = o
                        taken += 1 if (sp is not None or o is not None) else 0
                        continue
                    cur = self.pos_in(f, to_num(self.values.get(f["status"] or f["key"])))
                    if cur is not None:
                        w = self.line(f) == "w"
                        f["sv"][n - 1]["vw" if w else "v"] = cur
                        if f["key"] and f["type"] == "blind":
                            f["sv"][n - 1].pop("mw" if w else "m", None)    # Position gelernt
                        if f["type"] == "rgbw":
                            f["sv"][n - 1]["cw" if w else "c"] = self.current_color(f)
                        taken += 1
                self.last_event = "%s: Szene %d gelernt, %d Werte (%s)" % (g["name"], n, taken, source)
            else:
                self.active[gid] = n
                for k in [k for k in self.pending if k[0] == gid]:
                    self.pending.pop(k)
                why = {}
                for f in g["funcs"]:
                    en, v = self.entry(f, n)
                    if not en or not self.can_send(f):
                        continue
                    k = (gid, f["id"])
                    r = self.blocked(g, f, v)
                    if r:
                        self._defer(g, f, v, r)
                        for x in r:
                            why[x] = why.get(x, 0) + 1
                        continue
                    self.rain_hold.pop(k, None)       # neue Vorgabe ersetzt gemerkte Regen-Stellung
                    sends.append((f, v))
                self.last_event = "%s: Szene %d \"%s\" aufgerufen (%s), %d Werte%s (%s)" % (
                    g["name"], n, g["scenes"][n - 1]["name"].replace("\n", " "),
                    "Sommer" if self.summer else "Winter", len(sends),
                    "".join(", %d wegen %s zurueckgestellt" % (c, x) for x, c in sorted(why.items())), source)
        sent = self._send_all(sends)
        if learn:
            self._save_async()
        else:
            self._save_active_async(force=True)   # Szenenaufruf: Status wie bisher immer senden
        self._bump()
        self.debug.set("Letztes Ereignis", self.last_event)
        return {"ok": True, "sent": sent, "rev": self.rev}

    def _send_all(self, sends):
        """sends: Liste (Funktion, Befehl). Ist der Baustein nicht mit dem KO-Gateway verbunden und kommt der
        Auftrag von der Webseite, sendet die Seite die Werte über ihre eigene Gateway-Verbindung (page_send)."""
        n = 0
        collect = getattr(self._tl, "collect", None)
        for f, cmd in sends:
            kos = self.cmd_to_ko(f, cmd)
            if not kos:
                continue
            if collect is not None and not self.gw.connected:
                collect.extend([k, fmt_val(v)] for k, v in kos)
                n += 1
                continue
            if not self.gw.connected:
                self.last_event += " - Gateway nicht verbunden!"
                break
            if self._throttle()[0] > 0:
                self._enqueue(kos)
                n += 1
                continue
            ok = True
            for key, v in kos:
                ok = self.gw.set_value(key, v) and ok
            if ok:
                n += 1
            else:
                self.last_event += " - Gateway nicht verbunden!"
                break
        return n

    # ------------------------------------------------------------ v4.3: Sendebegrenzung (Buslast)
    def _throttle(self):
        c = self.config or {}
        return int(c.get("sendBurst", 5) or 0), float(c.get("sendPause", 1.0) or 0.0)

    def _enqueue(self, kos):
        with self._sq_cv:
            for key, v in kos:
                self._sq.pop(key, None)          # gleiches KO schon wartend -> nur den neuesten Wert senden
                self._sq[key] = v
            if self._sq_thread is None or not self._sq_thread.is_alive():
                self._sq_thread = threading.Thread(target=self._sq_loop, daemon=True)
                self._sq_thread.start()
            self._sq_cv.notify()

    def _sq_loop(self):
        while True:
            with self._sq_cv:
                while not self._sq:
                    if not self._sq_cv.wait(60):
                        if not self._sq:
                            self._sq_thread = None
                            return
                burst, pause = self._throttle()
                take = []
                while self._sq and (burst <= 0 or len(take) < burst):
                    take.append(self._sq.popitem(last=False))
                rest = len(self._sq)
            for key, v in take:
                if not self.gw.set_value(key, v):
                    self.gw.dlog("err", "Senden fehlgeschlagen (Warteschlange): %s" % key)
            if pause > 0:
                time.sleep(pause)
            self.debug_set("Warteschlange", "%d wartend" % rest)

    def debug_set(self, k, v):
        try:
            self.debug.set(k, v)
        except Exception:
            pass

    def set_cell_heat(self, g, f, s, en=None, v=None, winter=False, sp=None, o="keep"):
        """Heizung: Freigabe, Sollwert (v, gesendet nur mit sp) und Betriebsart (o, None = nicht senden)."""
        gid = g["id"]
        reasons = []
        with self._lock:
            e = f["sv"][s - 1]
            ke, kv, ksp, ko = ("ew", "vw", "spw", "ow") if winter else ("en", "v", "sp", "o")
            before = (bool(e.get(ke)), e.get(kv), bool(e.get(ksp)), e.get(ko))
            if en is not None:
                e[ke] = bool(en)
            if v is not None:
                nv = to_num(v)
                if nv is None:
                    return 400, {"error": "Wert ungültig"}
                e[kv] = min(f.get("max", 30), max(f.get("min", 5), nv))
                if sp is None:
                    sp = True                      # Sollwert eingestellt -> wird auch gesendet
            if sp is not None:
                e[ksp] = bool(sp)
            if o != "keep":
                e[ko] = norm_hvac(o)
            after = (bool(e.get(ke)), e.get(kv), bool(e.get(ksp)), e.get(ko))
            changed = after != before
            current = self.line(f) == ("w" if winter else "s")
            en_, cmd = self.entry(f, s, "w" if winter else "s")
            send = bool(changed and current and self.active.get(gid, 0) == s and en_ and self.can_send(f)
                        and self.cmd_to_ko(f, cmd))
            if send:
                reasons = self.blocked(g, f, cmd)
                if reasons:
                    send = False
                    self._defer(g, f, cmd, reasons)
                else:
                    self.pending.pop((gid, f["id"]), None)
        sent = self._send_all([(f, cmd)]) if send else 0
        if reasons or send:
            self._save_active_async()
        if changed:
            r = self._save_sync()
            if not r.get("ok"):
                return 500, r
        self._bump()
        return 200, {"ok": True, "sent": sent, "blocked": reasons, "rev": self.rev,
                     "other_season": bool(f.get("season") and not current)}

    def set_cell(self, gid, fid, s, en=None, v=None, winter=False, mode=None, color=None, heat=None):
        """Freigabe/Wert einer Zelle. mode: "pos" (Position/Wert) oder "move" (1 Bit fahren, nur Rollo/Fenster)."""
        reasons = []
        with self._lock:
            g = self._group(gid)
            f = self._func(g, fid) if g else None
            if f is None or not 1 <= s <= len(g["scenes"]):
                return 404, {"error": "Zelle nicht gefunden"}
            if f["type"] == "heat":
                heat = heat or {}
                is_heat = True
            else:
                is_heat = False
        if is_heat:
            return self.set_cell_heat(g, f, s, en, v, winter, heat.get("sp"), heat["o"] if "o" in heat else "keep")
        with self._lock:
            sv = f["sv"][s - 1]
            ke, kv, km = ("ew", "vw", "mw") if winter else ("en", "v", "m")
            kc = "cw" if winter else "c"
            e = {"en": bool(sv.get(ke)), "v": sv.get(kv, 0), "m": sv.get(km) or "pos"}
            if f["type"] == "rgbw":
                e["m"] = "rgbw"
                e["c"] = norm_color(sv.get(kc))
                if color is not None:
                    e["c"] = norm_color(color)
            before = dict(e)
            if en is not None:
                e["en"] = bool(en)
            if mode in ("pos", "move") and f["type"] == "blind":
                e["m"] = mode
            if v is not None:
                nv = to_num(v)
                if nv is None:
                    return 400, {"error": "Wert ungültig"}
                if f["type"] in ("switch", "lock"):
                    nv = 1 if nv >= 0.5 else 0
                elif f["type"] == "mode":
                    nv = int(round(nv))
                e["v"] = nv
            if e["m"] == "move":
                e["v"] = 100 if (to_num(e["v"]) or 0) >= 50 else 0     # Fahren nur bis Endlage
            sv[ke], sv[kv] = e["en"], e["v"]
            if f["type"] == "rgbw":
                sv[kc] = e["c"]
            elif e["m"] == "move":
                sv[km] = "move"
            else:
                sv.pop(km, None)
            changed = e != before
            current = self.line(f) == ("w" if winter else "s")    # bearbeitete Zeile gilt gerade
            cmd = (e["v"], e["m"], e["c"]) if f["type"] == "rgbw" else (e["v"], e["m"])
            send = bool(changed and current and self.active.get(gid, 0) == s and e["en"] and self.can_send(f)
                        and (e["v"] != before["v"] or e["m"] != before["m"] or e.get("c") != before.get("c")
                             or not before["en"]))
            if send:
                reasons = self.blocked(g, f, cmd)
                if reasons:
                    send = False
                    self._defer(g, f, cmd, reasons)
                else:
                    self.rain_hold.pop((gid, fid), None)
                    self.pending.pop((gid, fid), None)
            elif changed and current and self.active.get(gid, 0) == s and not e["en"]:
                self.pending.pop((gid, fid), None)
        sent = 0
        if send:
            sent = self._send_all([(f, cmd)])
        if reasons or send:
            self._save_active_async()
        if changed:
            r = self._save_sync()
            if not r.get("ok"):
                return 500, r
        self._bump()
        return 200, {"ok": True, "sent": sent, "blocked": reasons, "rev": self.rev,
                     "other_season": bool(f.get("season") and not current)}

    def set_live(self, gid, fid, v, mode=None, color=None, nosend=False, o="keep"):
        """„Aktuell“: sofort senden. mode "move" = Auf/Zu fahren (v 0/100), "stop" = Stopp.
        Heizung: v = Sollwert und/oder o = Betriebsart."""
        with self._lock:
            g = self._group(gid)
            f = self._func(g, fid) if g else None
            if f is None or not self.can_send(f):
                return 404, {"error": "Funktion nicht gefunden"}
            if f["type"] == "heat":
                nv = to_num(v) if v is not None else None
                if nv is not None:
                    nv = min(f.get("max", 30), max(f.get("min", 5), nv))
                cmd = (nv, "heat", norm_hvac(o) if o != "keep" else None)
                kos = self.cmd_to_ko(f, cmd)
                n = self.active.get(gid, 0)
                store = bool(g["liveToScene"] and 1 <= n <= len(g["scenes"]) and kos)
                if store:
                    w = self.line(f) == "w"
                    e = f["sv"][n - 1]
                    if nv is not None:
                        e["vw" if w else "v"], e["spw" if w else "sp"] = nv, True
                    if cmd[2] is not None:
                        e["ow" if w else "o"] = cmd[2]
                self.pending.pop((gid, fid), None)
                if not kos:
                    return 400, {"error": "Kein KO für diese Aktion eingetragen"}
            else:
                kos = None
        if kos is not None:
            if nosend:
                if store:
                    self._save_sync()
                self._bump()
                return 200, {"ok": True, "stored": store, "rev": self.rev, "kos": [[k, fmt_val(x)] for k, x in kos]}
            ok = True
            for key, val in kos:
                ok = self.gw.set_value(key, val) and ok
            if store:
                self._save_sync()
            self._bump()
            return (200 if ok else 503), {"ok": ok, "stored": store, "rev": self.rev,
                                          "error": None if ok else "KO-Gateway nicht verbunden"}
        with self._lock:
            g = self._group(gid)
            f = self._func(g, fid) if g else None
            if f is None:
                return 404, {"error": "Funktion nicht gefunden"}
            mode = mode if mode in ("move", "stop") and f["type"] == "blind" else ("rgbw" if f["type"] == "rgbw" else "pos")
            nv = to_num(v) if mode != "stop" else 0
            if nv is None:
                return 400, {"error": "Wert ungültig"}
            cmd = (nv, mode)
            if mode == "rgbw":
                cmd = (nv, "rgbw", norm_color(color) if color is not None else self.current_color(f))
            if mode == "move":
                cmd = (100 if nv >= 50 else 0, "move")
            n = self.active.get(gid, 0)
            line_w = self.line(f) == "w"
            kv, km = ("vw", "mw") if line_w else ("v", "m")
            store = bool(mode != "stop" and g["liveToScene"] and 1 <= n <= len(g["scenes"])
                         and (f["sv"][n - 1].get(kv) != cmd[0] or (f["sv"][n - 1].get(km) or "pos") != mode
                              or (mode == "rgbw" and f["sv"][n - 1].get("cw" if line_w else "c") != cmd[2])))
            if store:
                f["sv"][n - 1][kv] = cmd[0]
                if mode == "rgbw":
                    f["sv"][n - 1]["cw" if line_w else "c"] = cmd[2]
                elif mode == "move":
                    f["sv"][n - 1][km] = "move"
                else:
                    f["sv"][n - 1].pop(km, None)
            k = (gid, fid)
            self.pending.pop(k, None)                  # Handbedienung hat Vorrang
            if f.get("rain") and self.is_raining(g) and mode != "stop":
                if cmd[0] > 0:
                    self.rain_hold[k] = cmd            # nach dem Regen so wiederherstellen
                else:
                    self.rain_hold.pop(k, None)
        kos = self.cmd_to_ko(f, cmd)
        if not kos:
            return 400, {"error": "Kein KO für diese Aktion eingetragen"}
        ok = True
        if nosend:                                     # die Seite sendet selbst (wie die HTML5-Visu)
            self._save_active_async()
            if store:
                self._save_sync()
            self._bump()
            return 200, {"ok": True, "stored": store, "rev": self.rev, "kos": [[k, fmt_val(x)] for k, x in kos]}
        for key, val in kos:
            ok = self.gw.set_value(key, val) and ok
        self._save_active_async()
        if store:
            self._save_sync()
        self._bump()
        return (200 if ok else 503), {"ok": ok, "stored": store, "rev": self.rev,
                                      "error": None if ok else "KO-Gateway nicht verbunden"}

    # ------------------------------------------------------------ Speichern
    def _save_sync(self):
        return self._in_context(self._save_ctx, ())

    def _save_async(self):
        self.fw.run_in_context(self._save_ctx, ())

    def _save_active_async(self, force=False):
        self.fw.run_in_context(self._save_active_ctx, (force,))

    def _save_ctx(self, new_config=None):
        with self._lock:
            cfg = new_config if new_config is not None else self.config
            rev = max(int(time.time() * 1000), self.rev + 1)
            chunks = pack({"rev": rev, "config": cfg})
            if len(chunks) > CFG_STORES:
                return {"ok": False, "error": "Einrichtung zu gross (%d Zeichen komprimiert)" % sum(len(c) for c in chunks)}
            for k in range(1, CFG_STORES + 1):
                self.fw.set_store("c%02d" % k, chunks[k - 1] if k <= len(chunks) else b"")
            self.config, self.rev = cfg, rev
            # Aktive Szenen gelöschter Gruppen entfernen
            ids = set(g["id"] for g in cfg["groups"])
            self.active = dict((k, v) for k, v in self.active.items() if k in ids)
            self.rain_hold = dict((k, v) for k, v in self.rain_hold.items() if k[0] in ids)
        if new_config is not None:
            self._update_season()
            self._rebuild_pending()
        self._out("config_rev", float(rev) / 1000.0)
        self.debug.set("Einrichtung", "%s, %d Zeichen" % (time.strftime("%d.%m. %H:%M:%S"), sum(len(c) for c in chunks)))
        self._publish_outputs()
        self._bump()
        return {"ok": True, "rev": rev}

    def _save_gw_ctx(self, cfg, share=False, restart=True):
        """KO-Gateway-Zugang von der Webseite speichern (remanent) und neu verbinden."""
        url, user, pw = cfg
        self.fw.set_store("gw", json.dumps({"url": url, "user": user, "share": bool(share),
                                            "pw": base64.b64encode(pw.encode("utf-8")).decode("ascii")}).encode("ascii"))
        self.gw_share = bool(share)
        if restart or (url, user, pw) != self.gw_cfg:
            self.gw_cfg = (url, user, pw)
            self._start_gw()
        return {"ok": True}

    def _save_active_ctx(self, force=False):
        with self._lock:
            data = json.dumps({"a": self.active, "r": self._raining,
                               "h": [[k[0], k[1]] + list(v if isinstance(v, (tuple, list)) else (v, "pos"))
                                     for k, v in self.rain_hold.items()]}, separators=(",", ":"))
        self.fw.set_store("act", data.encode("ascii"))
        self._publish_outputs(force)

    def _out(self, name, value, force=False):
        """v4.2.2: Ausgang nur bei Änderung senden (force = beim Start / über E14 alle neu senden)."""
        last = getattr(self, "_last_out", None)
        if last is None:
            last = self._last_out = {}
        if force or last.get(name) != value:
            last[name] = value
            self.fw.set_output(name, value)

    def _publish_outputs(self, force=False):
        with self._lock:
            g = self.io_group()
            n = self.active.get(g["id"], 0) if g else 0
        if n:
            self._out("active", float((n - 1) & 0x3F), force)        # A2 DPT 17.001 (0 = Szene 1)
        for i in range(1, N_BITS + 1):                              # A3–A10 Szene 1–8 aktiv
            self._out("a%d" % i, 1.0 if n == i else 0.0, force)
        self._out("config_rev", float(self.rev) / 1000.0, force)
        self._out("gw_ok", 1.0 if self.gw.connected else 0.0, force)

    def _bump(self):
        with self._cond:
            self.seq += 1
            self._cond.notify_all()

    # ------------------------------------------------------------ HTTP-Server
    def _start_server(self):
        self._stop_server()
        try:
            httpd = ThreadingHTTPServer(("0.0.0.0", self.port), self._handler())
            httpd.daemon_threads = True
            httpd.timeout = 0.5
            stop = threading.Event()
            th = threading.Thread(target=self._serve, args=(httpd, stop), daemon=True)
            self._httpd, self._stop, self._thread = httpd, stop, th
            th.start()
            if self.port_missing:
                self._status("E2 Port fehlt! Im Experten 8093 eintragen, sonst leitet der HS nicht weiter (503)")
            else:
                self._status("Bereit: /%s/ (Port %d)%s" % (self.base_path, self.port, "" if self.key else " - OHNE Schluessel"))
        except OSError as e:
            self._status("Fehler beim Start auf Port %d: %s" % (self.port, e))

    @staticmethod
    def _serve(httpd, stop):
        try:
            while not stop.is_set():
                httpd.handle_request()
        finally:
            try:
                httpd.server_close()
            except OSError:
                pass

    def _stop_server(self):
        if self._stop is not None:
            self._stop.set()
        if self._thread is not None:
            self._thread.join(2.0)
        self._httpd = self._stop = self._thread = None

    def _handler(self):
        module = self

        class H(BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.0"
            server_version = "Szenen-Server-14778/" + VERSION
            sys_version = ""

            def log_message(self, *a):
                pass

            def do_GET(self):
                module._handle(self, "GET")

            def do_POST(self):
                module._handle(self, "POST")

            def do_OPTIONS(self):
                module._send(self, 204, "text/plain", b"")

        return H

    def page(self):
        if self._page is None:
            self._page = zlib.decompress(base64.b64decode(PAGE_Z))
        return self._page

    def _handle(self, h, method):
        try:
            parsed = urllib.parse.urlsplit(h.path)
            params = dict(urllib.parse.parse_qsl(parsed.query))
            route = parsed.path
            prefix = "/" + self.base_path
            if route == prefix or route.startswith(prefix + "/"):
                route = route[len(prefix):]
            route = route.strip("/")
            if route in ("", "index.html"):
                return self._send(h, 200, "text/html; charset=utf-8", self.page())
            if not self._authorized(h, params):
                return self._json(h, 401, {"error": "Schlüssel fehlt oder falsch"})
            body = None
            if method == "POST":
                body = self._read_body(h)
                if len(body) > MAX_BODY:
                    return self._json(h, 413, {"error": "Daten zu groß"})
            status, data = self.dispatch(method, route, params, body)
            self._json(h, status, data)
        except (ConnectionError, OSError):
            return
        except Exception as e:
            try:
                self._json(h, 500, {"error": "Interner Fehler: %r" % (e,)})
            except Exception:
                pass

    @staticmethod
    def _read_body(h):
        if "chunked" in (h.headers.get("Transfer-Encoding") or "").lower():
            out = b""
            while len(out) <= MAX_BODY:
                line = h.rfile.readline(100).strip()
                size = int(line.split(b";")[0] or b"0", 16)
                if size == 0:
                    h.rfile.readline(100)
                    break
                out += h.rfile.read(size)
                h.rfile.readline(10)
            return out
        n = int(h.headers.get("Content-Length") or 0)
        return h.rfile.read(min(n, MAX_BODY + 1)) if n > 0 else b""

    def _authorized(self, h, params):
        if not self.key:
            return True
        given = h.headers.get("X-Scene-Key") or params.get("key") or ""
        return hmac.compare_digest(given.encode("utf-8"), self.key.encode("utf-8"))

    # ------------------------------------------------------------ API (ohne Netzwerk testbar)
    def state(self):
        with self._lock:
            keys = set(k for k in (self.config["duskKey"], self.config["rainKey"], self.config["tempKey"]) if k)
            for g in self.config["groups"]:
                if g["triggerKey"]:
                    keys.add(g["triggerKey"])
                for f in g["funcs"]:
                    keys.update(func_keys(f))
            waiting = {}
            for (gid, fid), v in list(self.pending.items()) + list(self.rain_hold.items()):
                waiting.setdefault(gid, {})[fid] = "regen" if (gid, fid) in self.rain_hold else "bedingung"
            T = self.outdoor_avg()
            plans = {}
            for g in self.config["groups"]:
                for f in g["funcs"]:
                    if f["type"] == "heat" and f.get("plan", {}).get("on"):
                        plans[f["id"]] = self.plan_info(f, None, T)
            sensors = {"dark": self.is_dark(), "rain": self.is_raining(), "temp": self.temp(), "tavg": T, "plans": plans,
                       "summer": self.summer, "limit": self.config["tempLimit"],
                       "mean": self.season_mean(), "slots": list(self.sw["t"]), "slotDays": list(self.sw["d"]),
                       "src": {"dusk": self.config["duskKey"] or "E4", "rain": self.config["rainKey"] or "E15",
                               "temp": self.config["tempKey"] or "E16"}}
            return {"seq": self.seq, "rev": self.rev, "active": dict(self.active), "sensors": sensors, "waiting": waiting,
                    "values": dict((k, self.values[k]) for k in keys if k in self.values),
                    "errors": dict(self.key_errors),
                    "gw": {"ok": self.gw.connected, "msg": self.gw.msg}, "event": self.last_event}

    def dispatch(self, method, route, params, body):
        data = None
        if method == "POST":
            try:
                data = json.loads((body or b"{}").decode("utf-8"))
            except ValueError:
                return 400, {"error": "Kein gültiges JSON"}
            if not isinstance(data, dict):
                return 400, {"error": "JSON-Objekt erwartet"}
        if route == "api/log":
            with self._lock:
                items = list(self.gw.log)
            return 200, {"gw": {"ok": self.gw.connected, "msg": self.gw.msg, "url": self.gw_cfg[0], "user": self.gw_cfg[1]},
                         "subscribed": len(self.gw.subscribed), "errors": dict(self.key_errors),
                         "log": [[int(t * 1000), d, x] for t, d, x in items[-300:]]}
        if route == "api/ping":
            return 200, {"ok": True, "id": BLOCK_ID, "version": VERSION, "rev": self.rev,
                         "gw": self.gw.connected, "time": int(time.time() * 1000)}
        if route == "api/config" and method == "GET":
            with self._lock:
                return 200, {"rev": self.rev, "config": self.config, "version": VERSION}
        if route == "api/state":
            try:
                since = int(params.get("since", "0"))
                wait = max(0.0, min(25.0, float(params.get("wait", "0"))))
            except ValueError:
                since, wait = 0, 0.0
            end = time.time() + wait
            with self._cond:
                while self.seq <= since and time.time() < end:
                    self._cond.wait(min(1.0, end - time.time()))
            return 200, self.state()
        if route == "api/config" and method == "POST":
            if "config" not in data:
                return 400, {"error": "config fehlt"}
            with self._lock:
                if data.get("base") is not None and int(data.get("base") or 0) != self.rev:
                    return 409, {"error": "Die Einrichtung wurde inzwischen auf einem anderen Gerät geändert.",
                                 "rev": self.rev}
                cfg = norm_config(data["config"])
                self.key_errors = {}
            res = self._in_context(self._save_ctx, (cfg,))
            return (200 if res.get("ok") else 500), res
        if route == "api/value" and method == "POST":
            self._tl.collect = []
            try:
                heat = dict((k, data[k]) for k in ("sp", "o") if k in data)
                st, res = self.set_cell(str(data.get("g")), str(data.get("f")), int(data.get("s") or 0),
                                        data.get("en"), data.get("v"), bool(data.get("w")), data.get("m"), data.get("c"), heat)
                if self._tl.collect and isinstance(res, dict):
                    res["page_send"] = self._tl.collect
            finally:
                self._tl.collect = None
            return st, res
        if route == "api/set" and method == "POST":
            return self.set_live(str(data.get("g")), str(data.get("f")), data.get("v"), data.get("m"), data.get("c"),
                                 bool(data.get("nosend")), data["o"] if "o" in data else "keep")
        if route == "api/call" and method == "POST":
            self._tl.collect = []
            try:
                res = self.call_scene(str(data.get("g")), int(data.get("s") or 0), bool(data.get("learn")), "Webseite")
                if self._tl.collect:
                    res["page_send"] = self._tl.collect
            finally:
                self._tl.collect = None
            return (200 if res.get("ok") else 400), res
        if route == "api/gateway" and method == "GET":
            url, user, pw = self.gw_cfg
            res = {"url": url, "user": user, "has_pw": bool(pw), "share": self.gw_share and bool(user),
                   "ok": self.gw.connected, "msg": self.gw.msg}
            if res["share"]:
                res["pw"] = pw          # nur bei Freigabe "fuer alle Endgeraete" (Seite ist per Schluessel geschuetzt)
            return 200, res
        if route == "api/gateway" and method == "POST":
            if data.get("keep"):        # nur Freigabe aendern
                res = self._in_context(self._save_gw_ctx, (self.gw_cfg, bool(data.get("share")), False))
                return (200 if res.get("ok") else 500), res
            url = str(data.get("url") or "").strip()
            user = str(data.get("user") or "").strip()
            pw = data.get("pw")
            if pw is None:
                pw = self.gw_cfg[2] if user == self.gw_cfg[1] else ""
            res = self._in_context(self._save_gw_ctx, ((url, user, str(pw)), bool(data.get("share"))))
            return (200 if res.get("ok") else 500), res
        if route == "api/probe" and method == "POST":
            keys = data.get("keys") or []
            with self._lock:
                for k in keys:
                    self.key_errors.pop(norm_key(k), None)
            res = self.gw.probe(keys)
            if res is None:
                return 503, {"error": "KO-Gateway nicht verbunden"}
            return 200, {"codes": res}
        if route == "api/export":
            with self._lock:
                return 200, {"format": "szenen-server-export", "id": BLOCK_ID, "version": VERSION,
                             "exported_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                             "rev": self.rev, "config": self.config, "active": dict(self.active)}
        if route == "api/import" and method == "POST":
            if data.get("format") != "szenen-server-export" or not isinstance(data.get("config"), dict):
                return 400, {"error": "keine Szenen-Server-Sicherung"}
            merge = params.get("mode", "replace") == "merge"
            new = norm_config(data["config"])
            added = 0
            if merge:
                with self._lock:
                    cur = json.loads(json.dumps(self.config))
                have = dict((g["id"], g) for g in cur["groups"])
                for g in new["groups"]:
                    if g["id"] not in have:
                        cur["groups"].append(g)
                        added += len(g["funcs"])
                        continue
                    tg = have[g["id"]]
                    fids = set(f["id"] for f in tg["funcs"])
                    for f in g["funcs"]:
                        if f["id"] not in fids:
                            tg["funcs"].append(f)
                            added += 1
                new = norm_config(cur)
            res = self._in_context(self._save_ctx, (new,))
            res["mode"] = "merge" if merge else "replace"
            res["added"] = added
            return (200 if res.get("ok") else 500), res
        return 404, {"error": "unbekannt: " + route}

    def _in_context(self, fn, args, timeout=10):
        done = threading.Event()
        res = {}

        def run():
            try:
                res.update(fn(*args) or {})
            except Exception as e:
                res.update({"ok": False, "error": repr(e)})
            done.set()

        self.fw.run_in_context(run, ())
        if not done.wait(timeout):
            return {"ok": False, "error": "Zeitüberschreitung"}
        return res

    # ------------------------------------------------------------ Hilfen
    def _json(self, h, status, data):
        self._send(h, status, "application/json; charset=utf-8",
                   json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))

    @staticmethod
    def _send(h, status, ctype, body):
        h.send_response(status)
        h.send_header("Content-Type", ctype)
        h.send_header("Content-Length", str(len(body)))
        h.send_header("Cache-Control", "no-store")
        h.send_header("X-Content-Type-Options", "nosniff")
        h.send_header("Access-Control-Allow-Origin", "*")
        h.send_header("Access-Control-Allow-Headers", "X-Scene-Key, Content-Type")
        h.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        h.end_headers()
        if body:
            h.wfile.write(body)

    def _status(self, text):
        t = text
        for a, b in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("Ä", "Ae"), ("Ö", "Oe"), ("Ü", "Ue"),
                     ("ß", "ss"), ("–", "-"), ("…", "...")):
            t = t.replace(a, b)
        self.fw.set_output("status", t.encode("ascii", "replace")[:200])
        self.debug.set("Status", text)

    def fw_text(self, v):
        return self._text(v)

    @staticmethod
    def _text(v):
        if isinstance(v, bytes):
            try:
                return v.decode("utf-8")
            except UnicodeDecodeError:
                return v.decode("iso-8859-15", "replace")
        return "" if v is None else str(v)

    @staticmethod
    def _num(v, default):
        try:
            return float(v)
        except (TypeError, ValueError):
            return default
